						// will take care of it. However, @Data also wants a specific static name; this will be ignored; the appropriate way to do this is to use
						// the 'staticName' parameter of the @XArgsConstructor you've stuck on your type.
						// We should warn that we're ignoring @Data's 'staticConstructor' param.
						source.addWarning("Ignoring static constructor name: explicit @XxxArgsConstructor annotation present; its `staticName` parameter will be used.");
					}
					return;
				}
			}
		}
	}

	if (noArgs && noArgsConstructorAlreadyExists(typeNode)) return;

	if (!(skipIfConstructorExists != SkipIfConstructorExists.NO && constructorExists(typeNode) != MemberExistsResult.NOT_EXISTS)) {
		JCMethodDecl constr = buildTypeConstructor(staticConstrRequired ? AccessLevel.PRIVATE : level, onConstructor, typeNode, fields, allToDefault, source);
		attachConstructorJavadoc(constr, typeNode, fields);
		injectMethod(typeNode, constr);
	}
	generateStaticConstructorForType(staticConstrRequired, typeNode, staticName, level, allToDefault, fields, source);
}

public void generateStaticConstructorForType(boolean staticConstrRequired, JavacNode typeNode, String staticName, AccessLevel level, boolean allToDefault, List<JavacNode> fields, JavacNode source) {
	this.constructorType = typeNode;
	this.fieldScanType = typeNode;
	this.constructorAccess = level;
	this.constructorSource = source;
	this.constructorFields = fields;
	this.constructorStaticName = staticName;
	this.constructorAllToDefault = allToDefault;
	if (staticConstrRequired) {
		JCMethodDecl staticConstr = buildStaticConstructor(staticName, level, typeNode, allToDefault ? List.<JavacNode>nil() : fields, source);
		attachConstructorJavadoc(staticConstr, typeNode, fields);
		injectMethod(typeNode, staticConstr);
	}
}

public boolean noArgsConstructorAlreadyExists(JavacNode node) {
	if (this.constructorType != null) this.constructorAccess = this.constructorAccess;
	node = upToTypeNode(node);

	if (node != null && node.get() instanceof JCClassDecl) {
		for (JCTree def : ((JCClassDecl) node.get()).defs) {
			if (def instanceof JCMethodDecl) {
				JCMethodDecl md = (JCMethodDecl) def;
				if (md.name.contentEquals("<init>") && md.params.size() == 0) return true;
			}
		}
	}

	for (JavacNode child : node.down()) {
		if (annotationTypeMatches(NoArgsConstructor.class, child)) return true;
		if (annotationTypeMatches(RequiredArgsConstructor.class, child) && collectRequiredFields(node).isEmpty()) return true;
		if (annotationTypeMatches(AllArgsConstructor.class, child) && collectAllFields(node).isEmpty()) return true;
	}

	return false;
}

